-- generated by scripts/english-content/build-exam-seed.ts from supabase/content/english/exam (do not edit by hand)
-- Original practice papers for the national exam track (/exam), in the style of the
-- Multilevel exam. Not official papers. Idempotent: upserts by id.

-- multilevel-practice-1 (B1)
insert into public.english_exam_papers (id, exam, title, level_focus, status, content)
values ('multilevel-practice-1', 'multilevel', 'Practice paper 1', 'B1', 'published', $seed${"id":"multilevel-practice-1","title":"Practice paper 1","level_focus":"B1","reading":{"parts":[{"id":"r1","type":"gap_fill","level":"B1","title":"Part 1. Complete the text. Each missing word appears somewhere else in the text.","text":"Last month a new library opened in our town. The library is in the old cinema building near the bus station. Inside, there are more than ten thousand books and a quiet room for students who want to study. Many young people now go to the {{1}} after school because the study room has fast internet. On Saturdays there is a free English {{2}}. In the club, members read short stories and talk about them in English. You do not need to pay anything; you only need a library card. To get a {{3}}, bring your passport and a photo to the {{4}} on the first floor. The staff at the front desk are friendly and can help you find books. Some people say the old cinema was more fun, but most people {{5}} the library is better for the town. One student told me, 'I come here every day now. It is my favourite place to {{6}}.'","answers":{"1":"library","2":"club","3":"card","4":"desk","5":"say","6":"study"}},{"id":"r2","type":"mcq","level":"B1","title":"Part 2. Read the article and choose the correct answer.","text":"When Dilnoza finished school, she was not sure what to study at university. Her parents wanted her to become a doctor, but she was more interested in animals. Instead of choosing a course immediately, she decided to spend a year as a volunteer at the animal shelter in her city.\n\nThe shelter looks after around eighty dogs and cats that have lost their homes. Volunteers clean the rooms, prepare food and take the dogs for walks twice a day. At first, Dilnoza found the work tiring. 'I went home every evening with dirty clothes and sore feet,' she says. 'But after a few weeks I started to feel stronger, and I loved seeing the animals get healthier.'\n\nThe most difficult part of the job, she says, was not the physical work but saying goodbye. When a family adopts an animal, the volunteers are happy, but they also miss the animal they have cared for. Dilnoza remembers an old dog called Bars who waited almost a year for a new home. 'Everyone thought nobody would take him because of his age. Then a retired teacher came in and chose him immediately. I cried, but they were tears of joy.'\n\nThe year at the shelter helped Dilnoza make her decision. She has now started a degree in veterinary medicine. She still visits the shelter at weekends and encourages other young people to try volunteering before they choose a career. 'You learn what you really enjoy,' she says, 'and that is worth more than any test result.'","questions":[{"id":"1","prompt":"Why did Dilnoza start volunteering?","options":[{"id":"A","text":"Her parents asked her to."},{"id":"B","text":"She needed money for university."},{"id":"C","text":"She wanted time to decide what to study."},{"id":"D","text":"Her school required it."}],"answer":"C"},{"id":"2","prompt":"How did Dilnoza feel about the work at first?","options":[{"id":"A","text":"It was physically hard."},{"id":"B","text":"It was boring."},{"id":"C","text":"It was dangerous."},{"id":"D","text":"It was easy."}],"answer":"A"},{"id":"3","prompt":"What does Dilnoza say was the hardest part of the job?","options":[{"id":"A","text":"Cleaning the rooms."},{"id":"B","text":"Walking the dogs."},{"id":"C","text":"Working long hours."},{"id":"D","text":"Seeing animals leave."}],"answer":"D"},{"id":"4","prompt":"What was special about Bars?","options":[{"id":"A","text":"He was very young."},{"id":"B","text":"He had waited a long time for a home."},{"id":"C","text":"He belonged to a teacher before."},{"id":"D","text":"He was ill."}],"answer":"B"},{"id":"5","prompt":"Why did Dilnoza cry?","options":[{"id":"A","text":"She was sad that Bars was leaving her."},{"id":"B","text":"She was tired after a long day."},{"id":"C","text":"She was happy that Bars had found a home."},{"id":"D","text":"The teacher was rude to her."}],"answer":"C"},{"id":"6","prompt":"What advice does Dilnoza give young people?","options":[{"id":"A","text":"Try volunteering before choosing a career."},{"id":"B","text":"Choose the career your parents prefer."},{"id":"C","text":"Focus on your test results."},{"id":"D","text":"Study medicine."}],"answer":"A"}]},{"id":"r3","type":"headings","level":"B2","title":"Part 3. Choose the best heading for each paragraph. There are two headings you do not need.","headings":[{"id":"i","text":"Plan your money from the start"},{"id":"ii","text":"Make friends outside your course"},{"id":"iii","text":"Ask for help early"},{"id":"iv","text":"Look after your sleep"},{"id":"v","text":"Choose clubs carefully"},{"id":"vi","text":"Keep in touch with home"},{"id":"vii","text":"Learn to manage your time"},{"id":"viii","text":"Why grades matter most"}],"paragraphs":[{"id":"1","text":"At school, teachers tell you what to do and when. At university, you may have only fifteen hours of classes a week and a lot of free time. That freedom can be a trap. Successful students write a weekly timetable that includes reading, assignments and rest, and they treat study hours as seriously as lectures.","answer":"vii"},{"id":"2","text":"Many students receive their grant, or money from their parents, at the start of the month and have nothing left by the third week. Before you spend anything, write down your fixed costs: rent, transport and your phone. What is left is what you can really spend, and dividing it by four gives you a simple weekly limit.","answer":"i"},{"id":"3","text":"Feeling lost in a difficult subject is normal, but waiting until the exam to admit it is not. Tutors have office hours exactly for this reason, and most universities also offer free writing or maths support. Students who use these services in the first months usually avoid much bigger problems later.","answer":"iii"},{"id":"4","text":"Late-night conversations and online series are part of student life, yet research shows that students who regularly get less than six hours a night remember less of what they study. Try to go to bed at roughly the same time each night, especially in the weeks before exams.","answer":"iv"},{"id":"5","text":"It is natural to spend time with people from your own group, because you see them every day. However, your neighbours in the dormitory or students from other faculties can introduce you to new ideas and even future job opportunities. A wider circle also helps when the people you study with are busy.","answer":"ii"},{"id":"6","text":"Moving to a new city can make even confident students homesick. A short call to your family every few days keeps you connected without stopping you from building a new life. Some students also find it helps to bring a few familiar things, such as photos or a favourite blanket.","answer":"vi"}]},{"id":"r4","type":"mcq","level":"C1","title":"Part 4. Read the text and choose the correct answer.","text":"Teachers have long suspected that a good story sticks in the mind far longer than a list of facts, and cognitive scientists now have a fairly clear account of why. When we read a list, each item is stored more or less on its own, with few connections to anything else. A story, by contrast, links events through cause and effect: this happened because of that, and therefore something else followed. Each link acts as a retrieval cue, so that recalling one event tends to pull the next one with it.\n\nStories also engage emotion, and emotionally charged information is given priority by the brain. This is not simply a matter of excitement. Even mild curiosity, wanting to know what happens next, appears to prepare the brain to store new information, which may explain why students remember facts better when they are presented as answers to a question they have already started to wonder about.\n\nNone of this means that every lesson should be turned into a narrative. Critics point out that stories can be misleading precisely because they are memorable. A vivid anecdote about one patient who recovered after an unusual treatment may stay with us longer than the dull statistics showing that the treatment rarely works. In other words, the very features that make stories effective teaching tools also make them effective tools for spreading errors.\n\nThe practical lesson for learners is therefore a balanced one. Turning material into a story, by explaining to yourself why one event led to another or imagining how a historical figure might have felt, is a powerful way to remember it. But it should be combined with a habit of checking: asking whether the story fits the evidence, and whether a more boring explanation might be closer to the truth. Memorable and accurate are not the same thing, and good learners look for both.","questions":[{"id":"1","prompt":"According to the text, why are lists hard to remember?","options":[{"id":"A","text":"They are usually too long."},{"id":"B","text":"Their items have few links to each other."},{"id":"C","text":"They contain unfamiliar words."},{"id":"D","text":"They are rarely used in schools."}],"answer":"B"},{"id":"2","prompt":"In paragraph 1, a 'retrieval cue' is something that","options":[{"id":"A","text":"makes a story more exciting."},{"id":"B","text":"shows that an event is important."},{"id":"C","text":"replaces facts with emotions."},{"id":"D","text":"helps you bring back a related memory."}],"answer":"D"},{"id":"3","prompt":"What does the writer say about curiosity?","options":[{"id":"A","text":"It may help the brain prepare to remember."},{"id":"B","text":"It distracts students from facts."},{"id":"C","text":"It only matters in exciting stories."},{"id":"D","text":"It is stronger than other emotions."}],"answer":"A"},{"id":"4","prompt":"The example of the patient is used to show that","options":[{"id":"A","text":"doctors should tell more stories."},{"id":"B","text":"statistics are usually wrong."},{"id":"C","text":"a memorable story can give a false impression."},{"id":"D","text":"unusual treatments are often successful."}],"answer":"C"},{"id":"5","prompt":"What is the writer's attitude to using stories in lessons?","options":[{"id":"A","text":"Enthusiastic, without any doubts."},{"id":"B","text":"Positive, but with a warning."},{"id":"C","text":"Completely opposed."},{"id":"D","text":"Not interested."}],"answer":"B"},{"id":"6","prompt":"What does the writer advise learners to do?","options":[{"id":"A","text":"Avoid stories when studying history."},{"id":"B","text":"Memorise statistics instead of stories."},{"id":"C","text":"Only trust boring explanations."},{"id":"D","text":"Check whether a story matches the evidence."}],"answer":"D"}]}]},"listening":{"parts":[{"id":"l1","type":"dialogues","level":"B1","title":"Part 1. Listen to six short conversations. Choose the correct answer for each.","items":[{"id":"1","prompt":"Which bus should the woman take?","options":[{"id":"A","text":"Number two"},{"id":"B","text":"Number twelve"},{"id":"C","text":"Number twenty"}],"answer":"B","script":"Woman: Excuse me, does this bus go to the railway station?\nMan: No, you need the number twelve. It stops right across the road, next to the bank.\nWoman: Thanks. How often does it come?\nMan: About every ten minutes."},{"id":"2","prompt":"What time will they meet?","options":[{"id":"A","text":"At a quarter past six"},{"id":"B","text":"At six o'clock"},{"id":"C","text":"At half past six"}],"answer":"A","script":"Man: Shall we meet at six for the film?\nWoman: The film starts at half past six, but I finish work at six. Let's say a quarter past six, outside the cinema.\nMan: Fine, see you then."},{"id":"3","prompt":"What was the problem with the weekend?","options":[{"id":"A","text":"The hotel"},{"id":"B","text":"The views"},{"id":"C","text":"The weather"}],"answer":"C","script":"Woman: How was your weekend in the mountains?\nMan: The views were amazing, but it rained all Sunday, so we came back early. The hotel was nice, though.\nWoman: What a shame about the weather."},{"id":"4","prompt":"What does the man do in the end?","options":[{"id":"A","text":"He gets his money back."},{"id":"B","text":"He changes the jacket for a bigger one."},{"id":"C","text":"He buys a second jacket."}],"answer":"B","script":"Man: I'd like to return this jacket. It's too small.\nWoman: Would you like a bigger size or your money back?\nMan: Do you have it in large?\nWoman: Let me check. Yes, here you are."},{"id":"5","prompt":"Why won't the man go to the party?","options":[{"id":"A","text":"He has to prepare for an exam."},{"id":"B","text":"He is ill."},{"id":"C","text":"He wasn't invited."}],"answer":"A","script":"Woman: Are you coming to Aziz's birthday party on Friday?\nMan: I'd love to, but I have an exam on Saturday morning. I'll call him to say happy birthday instead.\nWoman: Good luck with the exam!"},{"id":"6","prompt":"What did the woman NOT buy?","options":[{"id":"A","text":"Tomatoes"},{"id":"B","text":"Rice"},{"id":"C","text":"Potatoes"}],"answer":"C","script":"Man: Did you buy the vegetables for dinner?\nWoman: I got tomatoes and onions, but the shop had no potatoes, so I bought some rice instead.\nMan: Rice is fine."}]},{"id":"l2","type":"notes","level":"B1","title":"Part 2. Listen to a talk about a summer camp. Complete the notes with ONE word or a number.","script":"Hello everyone, and welcome to this information session about our summer English camp. The camp takes place in the Chimgan mountains, about ninety kilometres from Tashkent. This year it runs from the fifth of July to the eighteenth of July, so that's two weeks in total. Students between fourteen and seventeen can apply. Every morning there are four hours of lessons, and in the afternoons students choose activities such as hiking, photography or drama. On the last evening, each group performs a short play in English for the parents. The price includes accommodation, all meals and transport by bus from the city centre. Students sleep in wooden cabins, with six students in each cabin. Please remember that phones are allowed only in the evening, between seven and nine. To apply, fill in the form on our website and send a short video introducing yourself. The deadline for applications is the first of June. If you have any questions, you can call the office or speak to me after this session.","notes":[{"id":"1","before":"Location: the","after":"mountains","answers":["chimgan"]},{"id":"2","before":"Dates: 5 July to","after":"July","answers":["eighteenth","18","18th","the eighteenth"]},{"id":"3","before":"Afternoon activities: hiking, photography or","after":"","answers":["drama"]},{"id":"4","before":"Students sleep in wooden","after":"(six in each)","answers":["cabins"]},{"id":"5","before":"Phones allowed only in the","after":"(7 to 9)","answers":["evening"]},{"id":"6","before":"To apply: fill in the form and send a short","after":"","answers":["video"]}]},{"id":"l3","type":"mcq","level":"B2","title":"Part 3. Listen to two students planning a presentation. Choose the correct answer.","script":"Kamola: So, have you looked at the topic for our presentation? Renewable energy in Central Asia.\nTimur: I have. I think we should focus on solar power. Uzbekistan has more than three hundred sunny days a year, so it's the obvious example.\nKamola: That's true, but the teacher said she wanted us to compare at least two sources of energy. If we only talk about solar, we'll lose marks.\nTimur: Fair point. What about wind, then? I read that there are big wind farm projects in Karakalpakstan.\nKamola: Good, that gives us a contrast. I can find the figures on wind if you take solar.\nTimur: Deal. How long does it need to be?\nKamola: Ten minutes, plus five minutes for questions. Honestly, it's the questions I'm worried about. Last time, the teacher asked about costs and nobody could answer.\nTimur: Then let's prepare a slide on costs, even if we don't show it. If someone asks, we'll have the numbers ready.\nKamola: Smart. And who's going to speak first?\nTimur: You should. You're more confident in front of people. I'll do the second half and the conclusion.\nKamola: All right, but you have to promise to practise. Last time you read everything from your notes.\nTimur: I know, I know. Let's rehearse together on Thursday evening in the library.\nKamola: Thursday doesn't work for me, I've got my part-time job. What about Wednesday?\nTimur: Wednesday's fine. Six o'clock?\nKamola: Perfect.","questions":[{"id":"1","prompt":"Why does Timur first suggest solar power?","options":[{"id":"A","text":"It is cheaper than other sources."},{"id":"B","text":"The country has a lot of sunshine."},{"id":"C","text":"The teacher recommended it."}],"answer":"B"},{"id":"2","prompt":"Why does Kamola not want to discuss only solar power?","options":[{"id":"A","text":"The task asks for a comparison."},{"id":"B","text":"She prefers wind power."},{"id":"C","text":"Solar power is too complicated."}],"answer":"A"},{"id":"3","prompt":"What is Kamola worried about?","options":[{"id":"A","text":"The length of the talk."},{"id":"B","text":"Finding the figures."},{"id":"C","text":"Answering questions."}],"answer":"C"},{"id":"4","prompt":"What does Timur suggest about costs?","options":[{"id":"A","text":"Leave them out completely."},{"id":"B","text":"Prepare the information in case it is needed."},{"id":"C","text":"Ask the teacher about them."}],"answer":"B"},{"id":"5","prompt":"Why should Kamola speak first?","options":[{"id":"A","text":"She knows more about the topic."},{"id":"B","text":"She has a part-time job."},{"id":"C","text":"She is more confident in front of people."}],"answer":"C"},{"id":"6","prompt":"When will they practise?","options":[{"id":"A","text":"On Wednesday evening."},{"id":"B","text":"On Thursday evening."},{"id":"C","text":"On Thursday afternoon."}],"answer":"A"}]},{"id":"l4","type":"mcq","level":"C1","title":"Part 4. Listen to part of a lecture. Choose the correct answer.","script":"Good afternoon. Today I want to look at a problem that most city dwellers have felt but few can name: the urban heat island. On a summer night, the centre of a large city can be several degrees warmer than the surrounding countryside. The reasons are fairly well understood. Asphalt and concrete absorb heat during the day and release it slowly after sunset, while buildings trap warm air and reduce the wind that would otherwise carry it away. Add the heat produced by cars and air conditioners, and you have a city that never really cools down.\nWhy does this matter? The obvious answer is comfort, but the more serious answer is health. Heat waves kill more people than most other kinds of extreme weather, and the victims are disproportionately elderly people living alone in top-floor flats. A city that stays hot at night denies their bodies the chance to recover.\nThe most popular solution is to plant trees, and trees certainly help, both by providing shade and by releasing moisture into the air. But I want to warn against seeing trees as a complete answer. A young tree takes years to grow a useful canopy, and in a dry climate it needs water that may be scarce. Some of the quickest gains, in fact, come from much less romantic measures: painting roofs in light colours so that they reflect sunlight, and replacing dark car parks with surfaces that let rain through.\nFinally, there is a question of fairness. Research from several cities shows that wealthier districts tend to have more green space and are therefore cooler. Any serious plan has to start with the neighbourhoods that are hottest, not those whose residents complain the loudest. That, I would argue, is the real test of whether a city takes the problem seriously.","questions":[{"id":"1","prompt":"What does the speaker mainly explain in the first part?","options":[{"id":"A","text":"Why city centres stay warmer than the countryside."},{"id":"B","text":"How air conditioners work."},{"id":"C","text":"The history of city planning."}],"answer":"A"},{"id":"2","prompt":"Why does the speaker mention elderly people in top-floor flats?","options":[{"id":"A","text":"To criticise building design."},{"id":"B","text":"To show who suffers most from the heat."},{"id":"C","text":"To explain why people move to the countryside."}],"answer":"B"},{"id":"3","prompt":"What is the speaker's view of planting trees?","options":[{"id":"A","text":"It is the only real solution."},{"id":"B","text":"It does more harm than good."},{"id":"C","text":"It helps, but it has limitations."}],"answer":"C"},{"id":"4","prompt":"Which measure does the speaker say can bring quick results?","options":[{"id":"A","text":"Growing large trees."},{"id":"B","text":"Light-coloured roofs."},{"id":"C","text":"Reducing traffic."}],"answer":"B"},{"id":"5","prompt":"What does 'much less romantic measures' suggest?","options":[{"id":"A","text":"They are practical rather than attractive."},{"id":"B","text":"They are very expensive."},{"id":"C","text":"Residents dislike them."}],"answer":"A"},{"id":"6","prompt":"According to the speaker, where should cooling plans start?","options":[{"id":"A","text":"In wealthy districts."},{"id":"B","text":"Where people complain the most."},{"id":"C","text":"In the hottest neighbourhoods."}],"answer":"C"}]}]},"writing":{"input":{"from":"Sardor Karimov, Club Manager","subject":"Changes to the Sunday football club","body":"Dear members,\n\nFrom next month, our Sunday football sessions will move from the city stadium to a new pitch on the edge of the city, and they will start at 8 a.m. instead of 10 a.m. The monthly membership fee will also rise slightly. We would like to hear what you think about these changes, and any ideas you have for the club.\n\nSardor Karimov, Club Manager"},"task11":"Write an email to your friend, who is also a member of the club. Tell your friend how you feel about the changes and what you are going to do. Write about 50 words.","task12":"Write an email to the club manager. Say how you feel about the changes and suggest what the club could do. Write 120-150 words.","part2":"You are writing a post for a popular education blog. The topic is: 'Schools should spend more time on sport, even if it means fewer hours for academic subjects.' Give your opinion and support your ideas with examples. Write 180-200 words."},"speaking":{"part11":["What do you usually do at the weekend?","Tell me about your favourite teacher.","What kind of food do you like to eat at home?"],"part12":{"scene":"Picture A: a family eating dinner together at a table at home. Picture B: a young man eating a sandwich alone at his desk while working on a laptop.","questions":["Describe and compare the two pictures. What do you see?","Why do some people prefer to eat with their family?","What are the disadvantages of eating while working?"]},"part2":{"scene":"A picture of an online lesson on a laptop screen, with many students in small video windows.","questions":["Tell me about a time when you learned something online.","What are the advantages and disadvantages of online learning?","Will online learning replace traditional schools in the future? Why or why not?"]},"part3":{"statement":"Young people should be allowed to vote from the age of 16.","for":["Many of them already work and pay taxes","Political decisions affect their future","It encourages an early interest in politics"],"against":["They may lack life experience","They can be easily influenced by others","Most of them still depend on their parents"]}}}$seed$::jsonb)
on conflict (id) do update set title = excluded.title, level_focus = excluded.level_focus, content = excluded.content, updated_at = now();

-- multilevel-practice-2 (B2)
insert into public.english_exam_papers (id, exam, title, level_focus, status, content)
values ('multilevel-practice-2', 'multilevel', 'Practice paper 2', 'B2', 'published', $seed${"id":"multilevel-practice-2","title":"Practice paper 2","level_focus":"B2","reading":{"parts":[{"id":"r1","type":"gap_fill","level":"B1","title":"Part 1. Complete the text. Each missing word appears somewhere else in the text.","text":"Every Sunday morning, a small market appears in the square in front of the old mosque. Farmers from nearby villages arrive early with their vegetables, fruit and fresh bread. By eight o'clock the square is full of people, and the smell of bread fills the air. Many families come to the {{1}} not only to shop but also to meet friends. Prices are usually lower than in the supermarket, and the {{2}} are often happy to give a better price if you buy a lot. One of the most popular stalls belongs to an old farmer who sells honey from his own bees. He lets visitors taste the {{3}} before they buy it. Children love the stall next to his, where a young woman sells hot {{4}} with cheese. In autumn there is even more {{5}}: melons, grapes and apples cover every table. For many people in the town, a Sunday without a short walk to the market is not a real Sunday, and they {{6}} their friends there every week.","answers":{"1":"market","2":"farmers","3":"honey","4":"bread","5":"fruit","6":"meet"}},{"id":"r2","type":"mcq","level":"B1","title":"Part 2. Read the article and choose the correct answer.","text":"At nineteen, Jasur Rakhimov has already built an app used by more than fifty thousand people. The idea came from a problem in his own family. His grandmother, who lives alone in a village near Samarkand, often forgot to take her medicine, and Jasur's mother worried about her constantly. 'There were reminder apps already,' Jasur explains, 'but they were all in English or Russian, and the buttons were too small for older people.'\n\nJasur taught himself programming from free online videos while he was still at school. His first version of the app was, in his words, 'terrible'. It crashed often, and the reminders sometimes came at the wrong time. Instead of giving up, he asked his grandmother and her neighbours to test each new version and tell him exactly what confused them. 'They were the best teachers I ever had,' he says. 'They didn't care about clever features. They wanted large letters, a loud sound and instructions in Uzbek.'\n\nThe app is free to download. Jasur earns a small income from a version for pharmacies, which can send messages to customers when their medicine is ready. He admits that the business is not making him rich, and that he has turned down an offer from a larger company to buy it. 'If I sell it, they might add advertising or make people pay,' he says. 'My grandmother's friends would stop using it.'\n\nNext year Jasur plans to study computer science abroad, but he intends to keep improving the app. 'My grandmother still sends me her ideas,' he laughs. 'Some of them are actually very good.'","questions":[{"id":"1","prompt":"Why did Jasur create the app?","options":[{"id":"A","text":"To win a programming competition."},{"id":"B","text":"To earn money for university."},{"id":"C","text":"Because his school asked him to."},{"id":"D","text":"To solve a problem in his family."}],"answer":"D"},{"id":"2","prompt":"What was wrong with the existing reminder apps, according to Jasur?","options":[{"id":"A","text":"They were not suitable for older Uzbek speakers."},{"id":"B","text":"They were too expensive."},{"id":"C","text":"They did not work without the internet."},{"id":"D","text":"They had too much advertising."}],"answer":"A"},{"id":"3","prompt":"How did Jasur improve the app?","options":[{"id":"A","text":"By taking a paid course."},{"id":"B","text":"By listening to older users' comments."},{"id":"C","text":"By copying other apps."},{"id":"D","text":"By hiring a designer."}],"answer":"B"},{"id":"4","prompt":"What did the older users care about most?","options":[{"id":"A","text":"Many clever features."},{"id":"B","text":"A modern look."},{"id":"C","text":"A simple, clear design."},{"id":"D","text":"A low price."}],"answer":"C"},{"id":"5","prompt":"Why has Jasur refused to sell the app?","options":[{"id":"A","text":"The offer was too low."},{"id":"B","text":"He wants to sell it later."},{"id":"C","text":"His family asked him not to."},{"id":"D","text":"He fears it would become worse for its users."}],"answer":"D"},{"id":"6","prompt":"How does Jasur feel about his grandmother's ideas?","options":[{"id":"A","text":"He thinks some of them are useful."},{"id":"B","text":"He finds them annoying."},{"id":"C","text":"He ignores them."},{"id":"D","text":"He doesn't understand them."}],"answer":"A"}]},{"id":"r3","type":"headings","level":"B2","title":"Part 3. Choose the best heading for each paragraph. There are two headings you do not need.","headings":[{"id":"i","text":"Research the organisation"},{"id":"ii","text":"Practise your answers out loud"},{"id":"iii","text":"Plan your journey"},{"id":"iv","text":"Prepare questions of your own"},{"id":"v","text":"Dress for the role"},{"id":"vi","text":"Say thank you afterwards"},{"id":"vii","text":"Ask for a higher salary straight away"},{"id":"viii","text":"Learn from rejection"}],"paragraphs":[{"id":"1","text":"Interviewers are rarely impressed by candidates who know nothing about them. Spend an hour on the company's website and recent news. Find out what it sells, who its customers are and what problems it might be facing. You can then link your experience to the company's real needs rather than speaking in general terms.","answer":"i"},{"id":"2","text":"Knowing what you want to say is not the same as being able to say it clearly under pressure. Ask a friend to play the interviewer and answer common questions aloud, such as why you want the job. You will quickly notice which answers are too long and which words you keep repeating.","answer":"ii"},{"id":"3","text":"There is no single correct outfit. A bank may expect a suit, while a design studio might find one strange. Look at photos of staff on the company's social media and choose clothes that are slightly smarter than what they wear every day. Whatever you choose, make sure it is clean and comfortable.","answer":"v"},{"id":"4","text":"Arriving late and out of breath is a terrible way to begin. Check the address the day before, find out how long the trip takes at that time of day and leave extra time for traffic. If possible, aim to be near the building fifteen minutes early, and use the time to calm down.","answer":"iii"},{"id":"5","text":"Most interviews end with the words 'Do you have any questions for us?' Saying no can suggest a lack of interest. Have two or three questions ready, for example about training or what a typical week looks like. Avoid anything you could easily have found out by reading the website.","answer":"iv"},{"id":"6","text":"Within a day of the interview, send a short, polite email to the people you met. Mention one thing from the conversation that made you more interested in the job. It takes five minutes, but many candidates forget, so it can help you stand out.","answer":"vi"}]},{"id":"r4","type":"mcq","level":"C1","title":"Part 4. Read the text and choose the correct answer.","text":"Few people today are ever truly bored. A spare minute in a queue or on a bus is filled almost automatically by a phone, and the feeling of having nothing to do has become something to be eliminated as quickly as possible. Yet a growing number of psychologists argue that in getting rid of boredom we may be losing something valuable.\n\nTheir argument rests on what boredom actually does. Far from being a passive state, boredom is an uncomfortable signal that our current activity is not meeting our needs. Like hunger, it pushes us to search for something better. In a well-known experiment, participants who first completed a deliberately dull task, copying numbers from a telephone directory, later produced more creative ideas than a group who had gone straight to the creative task. The researchers suggested that boredom had encouraged the participants' minds to wander, and that mind-wandering allowed unexpected connections to form.\n\nIt would be a mistake, however, to conclude that more boredom is always better. Chronic boredom, the kind experienced by people trapped in meaningless jobs or with no control over their days, is associated with poorer mental health rather than with creativity. The benefit seems to depend on the boredom being temporary and on the person having the freedom to act on the restlessness it produces.\n\nThis is where smartphones change the picture. The problem is not that phones are entertaining, but that they offer relief so quickly that the restlessness never has time to do its work. The mind is pulled back into a stream of content before it has wandered anywhere interesting. Some writers recommend 'boredom breaks': short periods, perhaps on a walk or a bus journey, when the phone stays in the bag and the mind is left to its own devices.\n\nWhether such advice will be widely followed is doubtful. Most people find boredom unpleasant, and technology companies are very good at offering alternatives. But for anyone who struggles to find new ideas, the occasional empty moment may be worth more than it seems.","questions":[{"id":"1","prompt":"What is the main point of the first paragraph?","options":[{"id":"A","text":"Phones are harmful to health."},{"id":"B","text":"Psychologists disagree about boredom."},{"id":"C","text":"People now avoid boredom almost completely."},{"id":"D","text":"Queues have become longer."}],"answer":"C"},{"id":"2","prompt":"Why does the writer compare boredom to hunger?","options":[{"id":"A","text":"Both are signals that push us to look for something."},{"id":"B","text":"Both are unpleasant physical feelings."},{"id":"C","text":"Both can be ignored safely."},{"id":"D","text":"Both are signs of illness."}],"answer":"A"},{"id":"3","prompt":"What did the experiment suggest?","options":[{"id":"A","text":"Dull tasks make people tired."},{"id":"B","text":"Copying numbers improves memory."},{"id":"C","text":"Creative people are rarely bored."},{"id":"D","text":"A boring task can lead to more creative thinking."}],"answer":"D"},{"id":"4","prompt":"According to the writer, when is boredom NOT helpful?","options":[{"id":"A","text":"When it lasts only a short time."},{"id":"B","text":"When it is long-term and people have little control."},{"id":"C","text":"When people are at work."},{"id":"D","text":"When people are outdoors."}],"answer":"B"},{"id":"5","prompt":"What is the writer's main concern about smartphones?","options":[{"id":"A","text":"They contain too much advertising."},{"id":"B","text":"They make people feel lonely."},{"id":"C","text":"They end restlessness before it can be useful."},{"id":"D","text":"They are too expensive for students."}],"answer":"C"},{"id":"6","prompt":"How does the writer see the chances of 'boredom breaks' becoming popular?","options":[{"id":"A","text":"Very likely."},{"id":"B","text":"Unlikely, although the idea has value."},{"id":"C","text":"Impossible to judge."},{"id":"D","text":"They are already common."}],"answer":"B"}]}]},"listening":{"parts":[{"id":"l1","type":"dialogues","level":"B1","title":"Part 1. Listen to six short conversations. Choose the correct answer for each.","items":[{"id":"1","prompt":"What time is the table booked for?","options":[{"id":"A","text":"Seven o'clock"},{"id":"B","text":"Eight o'clock"},{"id":"C","text":"Nine o'clock"}],"answer":"C","script":"Woman: Hi, I'd like to book a table for four for tomorrow evening.\nMan: Certainly. We have tables at seven or at nine.\nWoman: Seven is a bit early for us. We'll take the later one.\nMan: Nine o'clock, then. Can I have your name, please?"},{"id":"2","prompt":"Why is the woman moving?","options":[{"id":"A","text":"To study at a university."},{"id":"B","text":"To take a new role at work."},{"id":"C","text":"To live near her family."}],"answer":"B","script":"Man: Is it true you're moving to Bukhara?\nWoman: Yes, my company is opening an office there and I'll be the manager. I'm a bit nervous, but it's a great opportunity.\nMan: Congratulations!"},{"id":"3","prompt":"What is the problem with the printer?","options":[{"id":"A","text":"It has no ink."},{"id":"B","text":"It has no paper."},{"id":"C","text":"It is broken."}],"answer":"A","script":"Woman: The printer isn't working again.\nMan: Did you check the paper?\nWoman: There's plenty of paper. I think it's out of ink.\nMan: There's a new cartridge in the cupboard."},{"id":"4","prompt":"How did the woman travel today?","options":[{"id":"A","text":"By bicycle"},{"id":"B","text":"By metro"},{"id":"C","text":"By car"}],"answer":"A","script":"Man: How did you get here so fast?\nWoman: I usually take the metro, but today I borrowed my brother's bike. It's much quicker in the morning traffic."},{"id":"5","prompt":"Why does the woman choose the second phone?","options":[{"id":"A","text":"It has a better camera."},{"id":"B","text":"It is cheaper."},{"id":"C","text":"Its battery lasts longer."}],"answer":"C","script":"Woman: Which of these two phones would you recommend?\nMan: This one has a better camera, but the other one has a much longer battery life.\nWoman: I travel a lot, so the battery matters more to me.\nMan: Then the second one is right for you."},{"id":"6","prompt":"What is the woman waiting for?","options":[{"id":"A","text":"Charts from her manager."},{"id":"B","text":"Sales figures from a colleague."},{"id":"C","text":"The time of Monday's meeting."}],"answer":"B","script":"Man: Have you finished the report for Monday?\nWoman: Almost. I just need to add the charts, and Aziza promised to send me the sales figures tonight."}]},{"id":"l2","type":"notes","level":"B1","title":"Part 2. Listen to a museum guide. Complete the notes with ONE word or a number.","script":"Good morning and welcome to the Museum of Applied Arts. My name is Nilufar and I'll be your guide today. Before we start, a few practical points. The tour lasts about ninety minutes and we'll visit three halls. The building itself was built in the nineteenth century as the home of a wealthy diplomat, so please look up at the ceilings: they're decorated with traditional painted patterns. In the first hall you'll see embroidery called suzani, mostly from Bukhara and Nurata. The second hall is dedicated to ceramics, and the third to jewellery and wood carving. You are welcome to take photographs, but please don't use the flash, because strong light can damage the old fabrics. Halfway through the tour we'll stop for ten minutes in the courtyard, where there's a small cafe. At the end, the museum shop sells copies of some items, and all the money goes to restoration work. If you get lost, the exit is always signed in green. Right, please follow me.","notes":[{"id":"1","before":"Tour length: about","after":"minutes","answers":["ninety","90"]},{"id":"2","before":"The building was once the home of a","after":"","answers":["diplomat"]},{"id":"3","before":"Hall 1: embroidery called","after":"","answers":["suzani"]},{"id":"4","before":"Hall 2:","after":"","answers":["ceramics"]},{"id":"5","before":"Photos are allowed, but no","after":"","answers":["flash"]},{"id":"6","before":"Money from the shop pays for","after":"work","answers":["restoration"]}]},{"id":"l3","type":"mcq","level":"B2","title":"Part 3. Listen to a radio interview. Choose the correct answer.","script":"Presenter: My guest today is Malika Yusupova, who started a free running group in Tashkent three years ago. Malika, how did it begin?\nMalika: Quite by accident. I used to run alone in the park every Saturday, and a neighbour asked if she could join me. The next week she brought two friends, and it grew from there. Now we have around two hundred people on a good day.\nPresenter: That's a lot of people. Do you need to be fit to join?\nMalika: Not at all. That's the main thing I want people to understand. We have groups for every speed, including walkers. Some of our members couldn't run for one minute when they started.\nPresenter: What keeps people coming back?\nMalika: Honestly, it's less about the running than the company. People make friends, they have breakfast together afterwards. For some older members, it's the only time in the week they meet new people.\nPresenter: Has it been difficult to organise?\nMalika: The hardest part was safety. When we got bigger, we had to agree with the park managers on a route that doesn't cross any roads, and we trained volunteers in first aid.\nPresenter: And what's next for the group?\nMalika: We'd like to start a similar group in Samarkand. A few people there have already contacted us. But we don't want to grow too fast; the friendly atmosphere is what makes it work.","questions":[{"id":"1","prompt":"How did the running group start?","options":[{"id":"A","text":"Malika advertised it online."},{"id":"B","text":"A park manager suggested it."},{"id":"C","text":"A neighbour asked to run with Malika."}],"answer":"C"},{"id":"2","prompt":"What does Malika most want people to know?","options":[{"id":"A","text":"The group suits all fitness levels."},{"id":"B","text":"The group meets every day."},{"id":"C","text":"Members must run fast."}],"answer":"A"},{"id":"3","prompt":"According to Malika, why do people keep coming?","options":[{"id":"A","text":"To win races."},{"id":"B","text":"For the social side."},{"id":"C","text":"To lose weight."}],"answer":"B"},{"id":"4","prompt":"What was the biggest challenge?","options":[{"id":"A","text":"Finding volunteers."},{"id":"B","text":"Paying for the park."},{"id":"C","text":"Making the runs safe."}],"answer":"C"},{"id":"5","prompt":"What did the group do because of it?","options":[{"id":"A","text":"They chose a route that crosses no roads."},{"id":"B","text":"They moved to another park."},{"id":"C","text":"They limited the size of the group."}],"answer":"A"},{"id":"6","prompt":"What is Malika's attitude to growth?","options":[{"id":"A","text":"She wants to grow as fast as possible."},{"id":"B","text":"She is careful not to grow too quickly."},{"id":"C","text":"She wants to stop accepting new members."}],"answer":"B"}]},{"id":"l4","type":"mcq","level":"C1","title":"Part 4. Listen to a short talk. Choose the correct answer.","script":"In this short talk I'd like to consider why languages borrow words from one another, and why people often feel so strongly about it. Every language does it. English took thousands of words from French after the eleventh century, and Uzbek contains layers of Persian, Arabic and Russian vocabulary. More recently, almost every language has absorbed English words connected with technology.\nThe most obvious reason for borrowing is necessity. When a new object or idea arrives, it often brings its name with it, and it is simply easier to adopt that name than to invent a new one. But necessity alone doesn't explain everything. Many borrowed words replace perfectly good existing ones. Here the motive is usually prestige: speakers associate the source language with something desirable, such as modernity, education or wealth, and using its words lends them a little of that status.\nThis is precisely what tends to upset language purists. Their objection is rarely that the new words are hard to understand; it's that borrowing seems to signal a loss of confidence in one's own culture. Some governments have tried to respond by creating official native alternatives. The results are mixed. A replacement succeeds when it is short, easy to say and introduced early, before the borrowed word becomes established. Once a borrowing is in everyday use, official alternatives usually end up in dictionaries but not in people's mouths.\nIt's worth remembering, though, that borrowed words don't stay foreign for long. They are adapted to the sounds and grammar of the new language, often change their meaning, and within a generation or two most speakers no longer think of them as borrowed at all. From a historical point of view, borrowing is less a sign of a language's weakness than of its contact with the world.","questions":[{"id":"1","prompt":"What is the main purpose of the first part of the talk?","options":[{"id":"A","text":"To criticise English."},{"id":"B","text":"To show that all languages borrow words."},{"id":"C","text":"To compare French and Uzbek."}],"answer":"B"},{"id":"2","prompt":"What usually explains borrowing that replaces existing words?","options":[{"id":"A","text":"Prestige."},{"id":"B","text":"Necessity."},{"id":"C","text":"Government policy."}],"answer":"A"},{"id":"3","prompt":"What do purists mainly object to?","options":[{"id":"A","text":"Borrowed words are hard to understand."},{"id":"B","text":"Borrowed words are too long."},{"id":"C","text":"What borrowing seems to say about cultural confidence."}],"answer":"C"},{"id":"4","prompt":"When are official alternatives most likely to succeed?","options":[{"id":"A","text":"When they appear in dictionaries."},{"id":"B","text":"When they are introduced before the borrowed word spreads."},{"id":"C","text":"When they are longer and more formal."}],"answer":"B"},{"id":"5","prompt":"What happens to borrowed words over time?","options":[{"id":"A","text":"They become a normal part of the language."},{"id":"B","text":"They disappear."},{"id":"C","text":"They keep their original meaning."}],"answer":"A"},{"id":"6","prompt":"What is the speaker's overall view?","options":[{"id":"A","text":"Borrowing weakens languages."},{"id":"B","text":"Borrowing should be controlled by law."},{"id":"C","text":"Borrowing reflects contact with other cultures."}],"answer":"C"}]}]},"writing":{"input":{"from":"Gulnora Saidova, Events Coordinator, City Youth Centre","subject":"Language exchange evenings: new arrangements","body":"Dear volunteers,\n\nBecause of building repairs, our Thursday language exchange evenings will move to the second floor of the central library for the next three months. The sessions will be shorter, ninety minutes instead of two hours, and we can only accept thirty participants each time. Please let us know how you feel about these changes and whether you have any suggestions to help us organise the evenings.\n\nGulnora Saidova"},"task11":"Write an email to a friend who also volunteers at the evenings. Tell your friend how you feel about the changes and what you plan to do. Write about 50 words.","task12":"Write an email to the events coordinator. Explain how the changes affect you and suggest how the evenings could be organised. Write 120-150 words.","part2":"You are writing an article for an online magazine for young people. The topic is: 'Learning a foreign language is more useful today than ever before, even with translation apps.' Do you agree? Give your opinion and support it with examples. Write 180-200 words."},"speaking":{"part11":["Where do you live, and what do you like about it?","How do you usually spend your evenings?","What is your favourite season, and why?"],"part12":{"scene":"Picture A: a group of students studying together around a table in a library. Picture B: a student studying alone at home with headphones on.","questions":["Describe and compare the two pictures.","Why do some students prefer to study in groups?","What helps you to concentrate when you study?"]},"part2":{"scene":"A picture of a young person looking at several job offers on a laptop.","questions":["Tell me about an important choice you have made about your studies or work.","What do people think about when they choose a job?","Is it better to have a job you love or a job that pays well? Why?"]},"part3":{"statement":"Tourism does more good than harm to historic cities.","for":["It brings money and jobs to local people","It pays for the protection of old buildings","It helps people learn about other cultures"],"against":["It makes housing more expensive for residents","Crowds can damage historic sites","Local traditions can become shows for tourists"]}}}$seed$::jsonb)
on conflict (id) do update set title = excluded.title, level_focus = excluded.level_focus, content = excluded.content, updated_at = now();

-- multilevel-practice-3 (C1)
insert into public.english_exam_papers (id, exam, title, level_focus, status, content)
values ('multilevel-practice-3', 'multilevel', 'Practice paper 3', 'C1', 'published', $seed${"id":"multilevel-practice-3","title":"Practice paper 3","level_focus":"C1","reading":{"parts":[{"id":"r1","type":"gap_fill","level":"B1","title":"Part 1. Complete the text. Each missing word appears somewhere else in the text.","text":"When I moved into a student flat last year, I could not cook anything except eggs. For the first month I ate in cheap cafes, but soon I had no money left. My grandmother gave me a small book of family recipes, and I decided to try one recipe every week. The first {{1}} I tried was plov, and it was a disaster: the rice was hard and the meat was burnt. I called my grandmother, and she explained that I had used too much heat. The second time, the {{2}} was soft and the meat was perfect. Since then I have learned to make soup, salads and two kinds of bread. Cooking at home is much cheaper than eating in {{3}}, and it is also healthier. My flatmates now share the {{4}} for food, and in return I cook dinner for everyone on Sundays. Last month my {{5}} visited us and tasted my plov. She said it was almost as good as hers. Now I am the one who teaches my friends how to {{6}}.","answers":{"1":"recipe","2":"rice","3":"cafes","4":"money","5":"grandmother","6":"cook"}},{"id":"r2","type":"mcq","level":"B2","title":"Part 2. Read the article and choose the correct answer.","text":"When Rano Alimova decided to learn to drive at the age of sixty-one, her children thought she was joking. She had spent her whole life in the passenger seat, first beside her father and later beside her husband, and she had never felt the need to take the wheel herself. Everything changed when her husband's eyesight began to fail. 'Suddenly the person who drove us everywhere couldn't do it any more,' she says. 'Either I learned, or we stayed at home.'\n\nHer first lessons were, by her own account, frightening. Traffic in the city had become much heavier since her youth, and she found it difficult to watch the mirrors, the road and the instructor's hands at the same time. Several times she considered giving up. What kept her going, she says, was her instructor, a patient young man who never raised his voice and who suggested they practise early on Sunday mornings, when the roads were almost empty.\n\nRano failed her first driving test because she drove too slowly on the main road. She was disappointed but not discouraged. 'At my age, you know that mistakes are not the end of the world,' she explains. She passed at the second attempt, three months later.\n\nToday she drives her husband to his appointments and visits her grandchildren in a nearby town every weekend. She has also become something of a local celebrity: two of her neighbours, both women in their fifties, have started lessons with the same instructor. 'They saw that I could do it,' Rano says, 'so they stopped making excuses.'","questions":[{"id":"1","prompt":"Why did Rano decide to learn to drive?","options":[{"id":"A","text":"Her children encouraged her."},{"id":"B","text":"She wanted to find a job."},{"id":"C","text":"Her husband could no longer drive."},{"id":"D","text":"She had always dreamed of driving."}],"answer":"C"},{"id":"2","prompt":"What did Rano find most difficult in her first lessons?","options":[{"id":"A","text":"Paying attention to several things at once."},{"id":"B","text":"Understanding the rules."},{"id":"C","text":"Paying for the lessons."},{"id":"D","text":"Driving at night."}],"answer":"A"},{"id":"3","prompt":"Why did the instructor suggest Sunday mornings?","options":[{"id":"A","text":"He was free then."},{"id":"B","text":"The test centre was open."},{"id":"C","text":"Rano preferred them."},{"id":"D","text":"There was little traffic."}],"answer":"D"},{"id":"4","prompt":"Why did Rano fail her first test?","options":[{"id":"A","text":"She drove too fast."},{"id":"B","text":"She drove too slowly."},{"id":"C","text":"She forgot to check the mirrors."},{"id":"D","text":"She arrived late."}],"answer":"B"},{"id":"5","prompt":"How did Rano react to failing?","options":[{"id":"A","text":"She stopped her lessons for a year."},{"id":"B","text":"She changed instructors."},{"id":"C","text":"She complained about the examiner."},{"id":"D","text":"She stayed positive and tried again."}],"answer":"D"},{"id":"6","prompt":"What effect has Rano had on her neighbours?","options":[{"id":"A","text":"They now drive her around."},{"id":"B","text":"They think she is too old to drive."},{"id":"C","text":"They have started learning to drive."},{"id":"D","text":"They have bought new cars."}],"answer":"C"}]},{"id":"r3","type":"headings","level":"B2","title":"Part 3. Choose the best heading for each paragraph. There are two headings you do not need.","headings":[{"id":"i","text":"Plan meals before you shop"},{"id":"ii","text":"Understand date labels"},{"id":"iii","text":"Store food correctly"},{"id":"iv","text":"Use leftovers creatively"},{"id":"v","text":"Share what you cannot use"},{"id":"vi","text":"Turn scraps into compost"},{"id":"vii","text":"Buy only imported food"},{"id":"viii","text":"Eat out more often"}],"paragraphs":[{"id":"1","text":"Most food waste begins in the shop, not the kitchen. People buy what looks good or what is on special offer, then discover at home that they have no plan for it. Spending ten minutes on Sunday deciding what you will cook during the week, and writing a list based on that, can cut waste dramatically.","answer":"i"},{"id":"2","text":"Many products carry two different dates. A 'use by' date is about safety and should be taken seriously, especially for meat and dairy products. A 'best before' date, however, only tells you when the quality may start to decline. Rice or biscuits a day or two past that date are usually perfectly fine to eat.","answer":"ii"},{"id":"3","text":"Where you keep food matters as much as when you eat it. Tomatoes and bananas lose flavour in the fridge, while fresh herbs last much longer if you put them in a glass of water. Keeping older items at the front of the shelf also means you are more likely to use them first.","answer":"iii"},{"id":"4","text":"Yesterday's rice can become today's fried rice, and vegetables that are starting to soften are ideal for soup. Many traditional dishes around the world were originally invented as ways of using what was left from an earlier meal, so there is nothing second-class about cooking this way.","answer":"iv"},{"id":"5","text":"Sometimes you simply have more than your family can eat, for example after a celebration. Instead of throwing it away, offer it to neighbours, or use local community groups that connect people who have extra food with those who need it.","answer":"v"},{"id":"6","text":"Some waste cannot be avoided: vegetable peel, tea leaves, eggshells. If you have a garden or even a balcony, letting this material break down returns nutrients to the soil and reduces the amount of rubbish sent to landfill.","answer":"vi"}]},{"id":"r4","type":"mcq","level":"C1","title":"Part 4. Read the text and choose the correct answer.","text":"Few workplace ideas have spread as quickly in recent years as the four-day week. Trials in several countries have reported impressive results: employees working thirty-two hours instead of forty, with no loss of pay, said they were less stressed and slept better, while many employers found that productivity held steady or even rose. To its supporters, the case seems almost closed.\n\nEconomists, however, tend to be more cautious, and their reservations deserve attention. The first concerns the trials themselves. Companies that volunteer to take part are usually those whose managers already believe the idea will work, and whose work can be reorganised relatively easily. An advertising agency that cuts unnecessary meetings is a very different proposition from a hospital, a school or a bus company, where services must be provided every day and fewer hours per person simply means hiring more people.\n\nA second concern is what happens after the novelty wears off. Employees who know they are part of a high-profile experiment may work unusually hard to prove that it succeeds. Whether the same gains can be sustained over five or ten years, when the arrangement has become ordinary, is still largely unknown.\n\nNone of this means the idea is without merit. Even sceptics accept that much office work contains a great deal of wasted time, and that a shorter week can force organisations to identify and remove it. The more interesting question may not be whether the four-day week works, but for whom. A policy that suits software developers may be unworkable for nurses, and imposing one model on every sector would risk creating new inequalities between workers who can benefit and those who cannot.\n\nPerhaps the most realistic outcome is a gradual one. Rather than a single national change, we may see a patchwork of arrangements: four-day weeks in some industries, flexible hours in others, and in some sectors very little change at all. That may disappoint campaigners who hoped for a revolution, but it would reflect the very different realities of modern work.","questions":[{"id":"1","prompt":"What does the first paragraph say about the trials?","options":[{"id":"A","text":"Their results were disappointing."},{"id":"B","text":"They reported mostly positive results."},{"id":"C","text":"They only involved hospitals."},{"id":"D","text":"They reduced employees' pay."}],"answer":"B"},{"id":"2","prompt":"Why does the writer mention a hospital and a bus company?","options":[{"id":"A","text":"To praise their efficiency."},{"id":"B","text":"To show that they took part in trials."},{"id":"C","text":"To show where a shorter week is hardest to introduce."},{"id":"D","text":"To criticise their managers."}],"answer":"C"},{"id":"3","prompt":"What is the problem with companies that volunteer for trials?","options":[{"id":"A","text":"Their managers already expect the idea to work."},{"id":"B","text":"They are usually very large."},{"id":"C","text":"They do not measure productivity."},{"id":"D","text":"They pay their staff less."}],"answer":"A"},{"id":"4","prompt":"What does 'after the novelty wears off' refer to?","options":[{"id":"A","text":"When employees leave the company."},{"id":"B","text":"When managers change their minds."},{"id":"C","text":"When productivity falls."},{"id":"D","text":"When the arrangement is no longer new and special."}],"answer":"D"},{"id":"5","prompt":"According to the writer, what do even sceptics accept?","options":[{"id":"A","text":"The four-day week works everywhere."},{"id":"B","text":"Much office work involves wasted time."},{"id":"C","text":"Nurses want shorter weeks."},{"id":"D","text":"New national laws are needed."}],"answer":"B"},{"id":"6","prompt":"Which outcome does the writer consider most likely?","options":[{"id":"A","text":"A single national four-day week."},{"id":"B","text":"No change at all."},{"id":"C","text":"A return to longer hours."},{"id":"D","text":"Different arrangements in different sectors."}],"answer":"D"}]}]},"listening":{"parts":[{"id":"l1","type":"dialogues","level":"B1","title":"Part 1. Listen to six short conversations. Choose the correct answer for each.","items":[{"id":"1","prompt":"Which platform does the man need?","options":[{"id":"A","text":"Platform one"},{"id":"B","text":"Platform two"},{"id":"C","text":"Platform three"}],"answer":"C","script":"Man: Excuse me, is this the right platform for the train to Samarkand?\nWoman: No, that's platform three. This one is for Andijan. Go down the stairs and turn left.\nMan: Thank you very much."},{"id":"2","prompt":"What was the man's problem at the concert?","options":[{"id":"A","text":"The sound was poor."},{"id":"B","text":"His seat was far from the stage."},{"id":"C","text":"The band was late."}],"answer":"B","script":"Woman: Did you enjoy the concert?\nMan: The music was great, but we were sitting so far from the stage that we could hardly see the band.\nWoman: Next time, buy your tickets earlier."},{"id":"3","prompt":"When does the woman go to the gym now?","options":[{"id":"A","text":"At lunchtime"},{"id":"B","text":"Before work"},{"id":"C","text":"After work"}],"answer":"A","script":"Man: I'm thinking of joining the gym near the office.\nWoman: I joined last year. The equipment is good, but it's very crowded after work, so I go at lunchtime now.\nMan: Good idea."},{"id":"4","prompt":"What did the man change?","options":[{"id":"A","text":"He bought a new sofa."},{"id":"B","text":"He moved to a bigger flat."},{"id":"C","text":"He painted the walls and moved the furniture."}],"answer":"C","script":"Woman: Your flat looks different.\nMan: We painted the walls white and moved the sofa next to the window. It feels much bigger now.\nWoman: It really does."},{"id":"5","prompt":"When will they do the homework together?","options":[{"id":"A","text":"Tonight"},{"id":"B","text":"Tomorrow during the break"},{"id":"C","text":"After work tomorrow"}],"answer":"B","script":"Man: Can you help me with the maths homework tonight?\nWoman: I can't tonight, I'm working late. How about tomorrow during the break?\nMan: That's fine."},{"id":"6","prompt":"How much will the woman pay?","options":[{"id":"A","text":"Twenty thousand"},{"id":"B","text":"Forty thousand"},{"id":"C","text":"Nothing"}],"answer":"A","script":"Woman: How much is a ticket to the museum?\nMan: It's forty thousand for adults, but students pay half if they show their card.\nWoman: Great, here's my student card."}]},{"id":"l2","type":"notes","level":"B1","title":"Part 2. Listen to a phone message. Complete the notes with ONE word or a number.","script":"Hello, this is Bekzod calling from the Brightway Training Centre about your application for the evening web design course. I'm happy to tell you that there's still a place for you. The course starts on Monday the fourteenth and runs for ten weeks. Classes are on Mondays and Wednesdays from half past six to nine in the evening, in room twenty-two on the third floor. You'll need to bring your own laptop; if that's a problem, we can lend you one, but please tell us in advance. The fee can be paid in two parts: half before the course starts and half after five weeks. On the first evening there's a short test, just so the teacher can see what you already know, so don't worry about it. Please confirm your place by Friday, either by phone or by replying to our email. If we don't hear from you, we'll offer the place to someone on the waiting list. Thanks, and have a good day.","notes":[{"id":"1","before":"Course: evening","after":"design","answers":["web"]},{"id":"2","before":"Length:","after":"weeks","answers":["ten","10"]},{"id":"3","before":"Room:","after":"(third floor)","answers":["twenty-two","22","twenty two"]},{"id":"4","before":"Bring your own","after":"","answers":["laptop"]},{"id":"5","before":"First evening: a short","after":"(nothing to worry about)","answers":["test"]},{"id":"6","before":"Confirm your place by","after":"","answers":["friday"]}]},{"id":"l3","type":"mcq","level":"B2","title":"Part 3. Listen to two colleagues discussing a team trip. Choose the correct answer.","script":"Aziz: Have you seen the email about the team trip in May?\nLola: Yes. The manager wants us to choose between a weekend in Khiva and a day trip to the mountains.\nAziz: Khiva sounds amazing. I've never been.\nLola: It does, but think about the travel. It's a long journey, and half the team has small children. A whole weekend away is difficult for them.\nAziz: I hadn't thought of that. Still, a day in the mountains is just a long walk. We could do that any time.\nLola: Not really. The plan includes a guide who'll teach us about the plants and the history of the area, and there's lunch at a guesthouse. It's more than a walk.\nAziz: Okay, that sounds better. What about people who don't like hiking? Rustam hurt his knee last month.\nLola: The email says there's a shorter route along the river. He could take that and meet us for lunch.\nAziz: Fair enough. So you'll vote for the mountains?\nLola: I think so. Though if Khiva were closer, I'd choose it without hesitating.\nAziz: Maybe we could suggest Khiva for the autumn, as a longer trip with families invited.\nLola: That's a great idea. Let's put it in our reply.","questions":[{"id":"1","prompt":"What are the two options for the trip?","options":[{"id":"A","text":"Khiva or Samarkand."},{"id":"B","text":"Khiva or the mountains."},{"id":"C","text":"The mountains or the river."}],"answer":"B"},{"id":"2","prompt":"Why does Lola have doubts about Khiva?","options":[{"id":"A","text":"It is too expensive."},{"id":"B","text":"She has been there before."},{"id":"C","text":"It is hard for colleagues with young children."}],"answer":"C"},{"id":"3","prompt":"What makes the mountain trip more than a walk?","options":[{"id":"A","text":"A guide and lunch at a guesthouse."},{"id":"B","text":"A night in a hotel."},{"id":"C","text":"A sports competition."}],"answer":"A"},{"id":"4","prompt":"What could Rustam do?","options":[{"id":"A","text":"Stay at home."},{"id":"B","text":"Drive to the guesthouse."},{"id":"C","text":"Take a shorter route."}],"answer":"C"},{"id":"5","prompt":"How does Lola feel about Khiva?","options":[{"id":"A","text":"She would choose it if it were closer."},{"id":"B","text":"She dislikes it."},{"id":"C","text":"She thinks it is boring."}],"answer":"A"},{"id":"6","prompt":"What do they decide to suggest?","options":[{"id":"A","text":"Cancelling the trip."},{"id":"B","text":"An autumn trip to Khiva with families."},{"id":"C","text":"Two trips in May."}],"answer":"B"}]},{"id":"l4","type":"mcq","level":"C1","title":"Part 4. Listen to a short talk. Choose the correct answer.","script":"Over the past two decades, many schools have reduced the time spent teaching handwriting, on the reasonable assumption that most adult writing now happens on keyboards. It's a shift that seems sensible, but a growing body of research suggests we may want to be more careful about what we give up.\nThe central finding is fairly consistent. When students take lecture notes by hand, they tend to remember the content better than students who type, even though typists usually record more words. The leading explanation is that handwriting is slow. Because you cannot write down everything, you are forced to decide what matters and put it into your own words, and that act of selection and rephrasing is itself a form of learning. Typists, by contrast, can copy almost word for word, which requires much less thought.\nI'd add two qualifications. First, the advantage seems to depend on how the keyboard is used rather than on the keyboard itself. Students who are taught to summarise rather than copy while typing narrow the gap considerably. Second, for some learners, those with certain motor difficulties for instance, handwriting is so effortful that it gets in the way of thinking altogether, and for them a keyboard can be liberating.\nSo what should schools do? I'm not arguing for a return to hours of copying out letters. The skill worth protecting is not neat handwriting as such, but the habit of processing information actively. Handwriting happens to encourage that habit naturally, which is a good reason to keep it in classrooms, especially for note-taking. But the deeper goal should be to teach students how to listen, select and rephrase, whatever tool they happen to be holding.","questions":[{"id":"1","prompt":"Why did many schools teach less handwriting?","options":[{"id":"A","text":"Handwriting was thought to be harmful."},{"id":"B","text":"Teachers prefer typed work."},{"id":"C","text":"Most adults now write on keyboards."}],"answer":"C"},{"id":"2","prompt":"According to the research, why do handwritten notes help memory?","options":[{"id":"A","text":"Writing slowly forces students to select and rephrase."},{"id":"B","text":"Students write more words."},{"id":"C","text":"Handwritten notes look more attractive."}],"answer":"A"},{"id":"3","prompt":"What is the speaker's first qualification?","options":[{"id":"A","text":"Keyboards are always worse."},{"id":"B","text":"How the keyboard is used matters."},{"id":"C","text":"Typists remember more."}],"answer":"B"},{"id":"4","prompt":"Why does the speaker mention learners with motor difficulties?","options":[{"id":"A","text":"To argue for more handwriting practice."},{"id":"B","text":"To criticise keyboards."},{"id":"C","text":"To show that handwriting can be a barrier for some."}],"answer":"C"},{"id":"5","prompt":"What does the speaker think schools should protect?","options":[{"id":"A","text":"Neat handwriting."},{"id":"B","text":"The habit of processing information actively."},{"id":"C","text":"Hours of copying letters."}],"answer":"B"},{"id":"6","prompt":"Which best describes the speaker's position?","options":[{"id":"A","text":"Handwriting is useful mainly because it encourages active learning."},{"id":"B","text":"Handwriting should replace typing."},{"id":"C","text":"Typing should replace handwriting."}],"answer":"A"}]}]},"writing":{"input":{"from":"Customer Service, CityNet Home Internet","subject":"Planned service interruption and new prices","body":"Dear customer,\n\nOn 12 and 13 March, internet service in your area will be interrupted between 10 a.m. and 4 p.m. while we upgrade our equipment. From April, the monthly price of the Home Plus plan will increase by 15%, but the speed will double. Please tell us how these changes affect you and whether you would like to move to a different plan.\n\nCityNet Customer Service"},"task11":"Write an email to a friend who uses the same internet company. Tell your friend how you feel about the changes and what you are going to do. Write about 50 words.","task12":"Write an email to the customer service team. Explain how the changes affect you and say what you would like the company to do. Write 120-150 words.","part2":"You are writing a post for an online discussion forum. The topic is: 'Working from home is better for employees than working in an office.' Give your opinion and support it with reasons and examples. Write 180-200 words."},"speaking":{"part11":["What do you do to relax after a busy day?","Tell me about a place in your city that you like to visit.","How often do you use public transport?"],"part12":{"scene":"Picture A: a busy city street with tall buildings and heavy traffic. Picture B: a quiet village road with small houses and gardens.","questions":["Describe and compare the two pictures.","Why do many young people move from villages to cities?","Would you prefer to live in a city or a village in the future? Why?"]},"part2":{"scene":"A picture of a family sitting together at dinner, with everyone looking at their own phone.","questions":["Tell me about how technology has changed your daily life.","What are the positive and negative effects of smartphones on family life?","Should there be limits on how much time children spend on screens? Why?"]},"part3":{"statement":"University education should be free for all students.","for":["It gives equal chances to students from poor families","The country needs more educated people","Students can focus on study instead of part-time jobs"],"against":["It is very expensive for the government","Students may value free education less","The money could be spent on schools or hospitals instead"]}}}$seed$::jsonb)
on conflict (id) do update set title = excluded.title, level_focus = excluded.level_focus, content = excluded.content, updated_at = now();
